    testCases.forEach(
        ({
            part,
            xmlFile,
            subflowId,
            subflowName,
            inputCount,
            logActionId,
            logAnnotation,
            sampleInputs,
            datapillDataTypes,
        }) => {
            describe(`Part ${part}: ${subflowName}`, () => {
                test(`Round-trip: XML -> Fluent -> XML for Part ${part}`, async () => {
                    const project = ctx.createProject()

                    // Step 1: Load original XML
                    const originalXmlContent = loadTestFile(xmlFile, 'all-datatypes-datapills/xml')
                    expect(originalXmlContent).toBeTruthy()

                    const parser = new XMLParser({ ignoreAttributes: false })

                    // Step 2: XML -> Fluent transformation
                    const { changedFiles } = await project.transform({
                        path: xmlFile,
                        content: originalXmlContent,
                    })

                    expect(changedFiles).toHaveLength(1)
                    const fluentContent = changedFiles[0].getContent()
                    const fluentFileName = changedFiles[0].getName()

                    // Validate generated Fluent structure
                    expect(fluentContent).toContain(`export const alldatatypesvalidation_part${part}`)
                    expect(fluentContent).toContain(`$id: Now.ID['${subflowId}']`)
                    expect(fluentContent).toContain(`name: '${subflowName}'`)

                    // Validate input definitions in generated Fluent code
                    sampleInputs.forEach((inputName) => {
                        // Check that input is defined in the inputs section
                        const inputDefRegex = new RegExp(`${inputName}:\\s*(FlowArray|FlowObject|\\w+Column)\\(`)
                        expect(fluentContent).toMatch(inputDefRegex)

                        // For GenericColumn inputs, verify columnType matches the datatype
                        // Use regex with word boundary to avoid partial matches (e.g., template_value vs snapshot_template_value)
                        const genericColumnRegex = new RegExp(`\\b${inputName}:\\s*GenericColumn\\(`)

                        if (genericColumnRegex.test(fluentContent)) {
                            const expectedDatatype = datapillDataTypes[inputName as keyof typeof datapillDataTypes]
                            // Extract the section for this input and check columnType
                            const match = fluentContent.match(genericColumnRegex)
                            if (match) {
                                const startIdx = match.index!
                                const inputSection = fluentContent.substring(startIdx, startIdx + 300)
                                expect(inputSection).toContain(`columnType: '${expectedDatatype}'`)
                            }
                        }
                    })

                    // Validate datapills in log message
                    sampleInputs.forEach((inputName) => {
                        const expectedDatatype = datapillDataTypes[inputName as keyof typeof datapillDataTypes]
                        expect(fluentContent).toContain('wfa.dataPill(')
                        expect(fluentContent).toContain(`_params.inputs.${inputName}`)
                        expect(fluentContent).toContain(
                            `wfa.dataPill(_params.inputs.${inputName}, '${expectedDatatype}')`
                        )
                    })

                    // Step 3: Fluent -> XML transformation (use dynamically generated Fluent code)
                    const tempProject = ctx.createProject()
                    tempProject.addFile({ path: fluentFileName, content: fluentContent })

                    const output = await tempProject.getFile(fluentFileName)!.getOutput()
                    expect(output.length).toBeGreaterThan(0)

                    const regeneratedXmlContent = output[0].content
                    const regeneratedParsed = parser.parse(regeneratedXmlContent)

                    // Step 4: Validate regenerated XML
                    expect(regeneratedParsed.record_update).toBeDefined()
                    const regeneratedSubflow = regeneratedParsed.record_update.sys_hub_flow
                    expect(regeneratedSubflow).toBeDefined()

                    // Validate subflow metadata
                    expect(regeneratedSubflow.sys_id).toBe(subflowId)
                    expect(regeneratedSubflow.internal_name).toBe(`alldatatypesvalidation_part${part}`)
                    expect(regeneratedSubflow.description).toBe(
                        `Comprehensive test subflow with ServiceNow datatypes - Part ${part} of 11`
                    )
                    expect(regeneratedSubflow.generation_source).toBe('fluent')
                    // expect(regeneratedSubflow.active).toBe('true') // Not validating active status

                    // Validate inputs
                    expect(regeneratedParsed.record_update.sys_hub_flow_input).toBeDefined()
                    const regeneratedInputs = Array.isArray(regeneratedParsed.record_update.sys_hub_flow_input)
                        ? regeneratedParsed.record_update.sys_hub_flow_input
                        : [regeneratedParsed.record_update.sys_hub_flow_input]

                    expect(regeneratedInputs.length).toBe(inputCount)

                    // Validate each sample input exists
                    sampleInputs.forEach((inputName) => {
                        const input = regeneratedInputs.find((inp: any) => inp.element === inputName)
                        expect(input).toBeDefined()
                        expect(input.label).toBeTruthy()
                        expect(input.model).toBe(subflowId)
                    })

                    // Validate log action
                    expect(regeneratedParsed.record_update.sys_hub_action_instance_v2).toBeDefined()
                    const regeneratedActions = Array.isArray(regeneratedParsed.record_update.sys_hub_action_instance_v2)
                        ? regeneratedParsed.record_update.sys_hub_action_instance_v2
                        : [regeneratedParsed.record_update.sys_hub_action_instance_v2]

                    const regeneratedLogAction = regeneratedActions.find((act: any) => act.sys_id === logActionId)
                    expect(regeneratedLogAction).toBeDefined()
                    expect(regeneratedLogAction.comment).toBe(logAnnotation)
                    expect(regeneratedLogAction.flow).toBe(subflowId)

                    // Validate dataPills in the gzip-compressed log action inputs
                    expect(regeneratedLogAction.values).toBeDefined()
                    const decompressedInputs = unzipInputArray(regeneratedLogAction.values)
                    expect(Array.isArray(decompressedInputs)).toBe(true)

                    // Find the log_message parameter
                    const logMessageParam = decompressedInputs.find((input: any) => input.name === 'log_message')
                    expect(logMessageParam).toBeDefined()
                    expect(logMessageParam.value).toBeDefined()

                    const logMessage = logMessageParam.value.toString()

                    // Validate each sampleInput appears in the log message with correct dataPill reference
                    sampleInputs.forEach((inputName) => {
                        // Check for dataPill reference format: {{subflow.inputName}}
                        expect(logMessage).toContain(`{{subflow.${inputName}}}`)
                    })

                    // Validate label_cache contains all inputs that have dataPills
                    expect(regeneratedSubflow.label_cache).toBeDefined()
                    const labelCache = JSON.parse(regeneratedSubflow.label_cache)
                    expect(Array.isArray(labelCache)).toBe(true)
                    expect(labelCache.length).toBeGreaterThanOrEqual(sampleInputs.length)

                    // Validate each input is in label_cache
                    sampleInputs.forEach((inputName) => {
                        const cacheEntry = labelCache.find((entry: any) => entry.name === `subflow.${inputName}`)
                        expect(cacheEntry).toBeDefined()
                        expect(cacheEntry.usedInstances).toBeDefined()
                    })

                    // Round-trip validation complete - regenerated XML has been validated for:
                    // - Correct subflow metadata (sys_id, internal_name, description, generation_source)
                    // - All inputs with correct labels and models
                    // - Log action with correct comment and flow reference
                    // - Label cache with all dataPill inputs
                })
            })
        }
    )
